//! Bengali word suggestions for `upodesh`.
//!
//! This crate takes **already-converted Bengali text** and returns ranked,
//! typo-tolerant suggestions. Phonetic/Avro/Khipro conversion belongs to
//! `riti`/`okkhor`, not here.
//!
//! The correction engine indexes dictionary words as sequences of extended
//! grapheme clusters in a grapheme trie and searches it with a weighted
//! Damerau/optimal-string-alignment dynamic program. The same trie answers
//! prefix completion, so there is no separate prefix-suggestion path.
//!
//! The dictionary is generated by `build.rs` as an embedded FST blob;
//! `Corrector::from_bytes` streams it into the trie once, on first use.

use std::sync::OnceLock;

pub mod typo;

pub use typo::{
    BigramLanguageModel, BuildError, ClassWeights, Correction, CorrectionConfig, Corrector,
    EditCosts, IndexStats, InputMode, LemmaPos, LemmaTable, Morphology, SuffixRule, Suggestion,
    SuggestionInput, TrigramLanguageModel, WordEntry,
};

/// Build-time generated grapheme table + FST blob, see `build.rs`.
static CORRECTOR: OnceLock<Corrector> = OnceLock::new();
static EMPTY: OnceLock<Corrector> = OnceLock::new();

fn empty_corrector() -> &'static Corrector {
    EMPTY.get_or_init(|| {
        Corrector::from_words(std::iter::empty::<&str>())
            .unwrap_or_else(|_| Corrector::empty_fallback())
    })
}

/// Load an owned copy of the embedded index, e.g. to apply a custom
/// `CorrectionConfig` or `EditCosts` through the `with_*` builders.
///
/// Each call decodes the embedded blob again; use [`corrector`] for the
/// shared default instance.
pub fn load_embedded() -> Result<Corrector, BuildError> {
    Corrector::from_bytes(include_bytes!(concat!(
        env!("OUT_DIR"),
        "/dictionary.index"
    )))
}

/// Return the shared correction index.
///
/// The embedded blob is decoded once into the grapheme trie on first use;
/// there is no dictionary parse after that. If the embedded index is
/// unreadable, returns an empty index instead of panicking.
pub fn corrector() -> &'static Corrector {
    if let Some(c) = CORRECTOR.get() {
        return c;
    }
    match load_embedded() {
        Ok(c) => CORRECTOR.get_or_init(|| c),
        Err(_) => empty_corrector(),
    }
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeMap;

    use serde_json::Value;
    use simd_normalizer::UnicodeNormalization;

    use super::*;

    fn dictionary_entries() -> Vec<WordEntry> {
        let root: Value = serde_json::from_str(include_str!(
            "../data/openbangla-keyboard/data/dictionary.json"
        ))
        .expect("embedded dictionary is valid JSON");
        let frequencies: BTreeMap<String, u64> =
            serde_json::from_str(include_str!("../data/frequency.json"))
                .expect("frequency table is valid JSON");
        let mut entries = Vec::new();
        for words in root.as_object().into_iter().flat_map(|b| b.values()) {
            for word in words.as_array().into_iter().flatten() {
                if let Some(word) = word.as_str() {
                    let normalized: String = word.nfc().into_owned();
                    let frequency = frequencies.get(&normalized).copied().unwrap_or(1);
                    entries.push(WordEntry::new(normalized, frequency));
                }
            }
        }
        let lemma: BTreeMap<String, String> =
            serde_json::from_str(include_str!("../data/lemma.json"))
                .expect("lemma table is valid JSON");
        let mut frequencies_by_word = BTreeMap::<String, u64>::new();
        for entry in &entries {
            let slot = frequencies_by_word.entry(entry.word.clone()).or_default();
            *slot = slot.saturating_add(entry.frequency.max(1));
        }
        for (word, frequency) in
            crate::typo::derive::genitive_forms(&frequencies_by_word, &lemma, &frequencies)
        {
            entries.push(WordEntry::new(word, frequency));
        }
        entries
    }

    #[test]
    fn embedded_index_contains_the_full_dictionary() {
        let corrector = corrector();
        assert!(
            corrector.len() > 150_000,
            "expected the full OpenBangla-Keyboard dictionary, got {} entries",
            corrector.len()
        );
    }

    #[test]
    fn embedded_index_matches_in_memory_build() {
        // Guards against `build.rs` drifting from `Corrector::from_entries`.
        let embedded = corrector();
        let in_memory = Corrector::from_entries(dictionary_entries()).unwrap();
        assert_eq!(embedded.len(), in_memory.len());
        for query in ["বাংলা", "বাংরা", "আমি", "কম্পিউটার"]
        {
            assert_eq!(
                embedded.suggest_with(query, 10),
                in_memory.suggest_with(query, 10),
                "query {query}"
            );
        }
    }

    #[test]
    fn corrector_answers_bangla_queries() {
        let corrector = corrector();
        assert!(corrector.contains("বাংলা"));
        assert_eq!(corrector.suggest_with("বাংলা", 1), vec!["বাংলা"]);
        assert!(
            corrector
                .complete_prefix("বাংলা", 10)
                .iter()
                .any(|word| word == "বাংলাদেশ"),
            "prefix completion should return words starting with বাংলা"
        );
    }

    #[test]
    fn suggest_input_ranks_the_closest_roman_match_first() {
        let corrector = corrector();
        for (roman, bangla, mode, expected) in [
            ("sonar", "সনার", InputMode::Avro, "সোনার"),
            ("bangla", "বাংলা", InputMode::Avro, "বাংলা"),
            ("kintu", "কিন্তু", InputMode::Avro, "কিন্তু"),
        ] {
            let query = SuggestionInput::with_roman(roman, bangla, mode);
            let top = corrector.suggest_input(&query, 5);
            assert_eq!(
                top.first().map(|s| s.word.as_str()),
                Some(expected),
                "{roman}: {top:?}"
            );
        }
    }

    #[test]
    fn complete_prefix_only_returns_extensions_of_the_prefix() {
        let corrector = corrector();
        for prefix in ["আম", "বাং", "কিং", "প্রি", "পৃ"] {
            let completions = corrector.complete_prefix(prefix, 8);
            assert!(!completions.is_empty(), "{prefix} produced no completions");
            for word in &completions {
                assert!(
                    word.starts_with(prefix),
                    "{word} does not start with {prefix}"
                );
                assert!(corrector.contains(word), "{word} is not an indexed word");
            }
        }
    }

    #[test]
    fn roman_queries_rank_the_intended_word_first() {
        // Regressions from OpenBangla/next-gen-ime#4.
        let corrector = corrector();
        for (roman, bangla, expected) in [
            ("kingkortobbobimur", "কিংকর্তব্ববিমুর", "কিংকর্তব্যবিমূঢ়"),
            ("prithibir", "প্রিথিবির", "পৃথিবীর"),
            ("chino", "ছিন", "চিনো"),
        ] {
            let query = SuggestionInput::with_roman(roman, bangla, InputMode::Avro);
            let top = corrector.suggest_input(&query, 5);
            assert_eq!(
                top.first().map(|s| s.word.as_str()),
                Some(expected),
                "{roman}: {top:?}"
            );
        }
    }

    #[test]
    fn typo_tolerant_lookup_recovers_a_plausible_spelling() {
        let corrector = corrector();
        assert!(
            corrector
                .suggest_with("বাংলাা", 5)
                .iter()
                .any(|word| word == "বাংলা"),
            "an extra vowel sign should still recover বাংলা"
        );
        assert!(
            corrector
                .suggest_with("বাংরা", 10)
                .iter()
                .any(|word| word == "বাংলা"),
            "the frequency prior should keep বাংলা in the top 10"
        );
    }
}
